import React, {type ReactNode} from 'react';
import {PageMetadata} from '@docusaurus/theme-common';
import {useDoc} from '@docusaurus/plugin-content-docs/client';
import useDocusaurusContext from '@docusaurus/useDocusaurusContext';

/**
 * Same as the default DocItem/Metadata, with a per-page social preview image
 * (static/img/og/<locale>/<doc id>.png, generated by scripts/build_og.py)
 * when the page does not set `image` in its front matter.
 */
export default function DocItemMetadata(): ReactNode {
  const {metadata, frontMatter, assets} = useDoc();
  const {i18n} = useDocusaurusContext();
  const generated = `/img/og/${i18n.currentLocale}/${metadata.id}.png`;
  return (
    <PageMetadata
      title={metadata.title}
      description={metadata.description}
      keywords={frontMatter.keywords}
      image={assets.image ?? frontMatter.image ?? generated}
    />
  );
}
